tests:
from decimal import Decimal
assert csv_totals('category,amount
') == {}
assert csv_totals('category,amount
A,0.1
A,0.2
B,-2.5

') == {'A': Decimal('0.3'), 'B': Decimal('-2.5')}
assert csv_totals('category,amount
"a,b",1.20
"a,b",2.30
') == {'a,b': Decimal('3.50')}
try:
    csv_totals('category,amount
A,nope
')
except ValueError:
    pass
else:
    raise AssertionError('invalid amount accepted')

assert topo_sort({}) == []
g = {'b':['c'], 'a':['c'], 'd':[]}
assert topo_sort(g) == ['a','b','c','d']
assert g == {'b':['c'], 'a':['c'], 'd':[]}
assert topo_sort({'z':['a']}) == ['z','a']
assert topo_sort({'a':['c','c'], 'b':['c']}) == ['a','b','c']
for g in ({'a':['a']}, {'a':['b'],'b':['a']}):
    try:
        topo_sort(g)
    except ValueError:
        pass
    else:
        raise AssertionError('cycle accepted')

a = {'x':{'a':1,'items':[1]},'left':[{'v':2}]}
b = {'x':{'b':2},'right':[3]}
r = deep_merge(a,b)
assert r == {'x':{'a':1,'items':[1],'b':2},'left':[{'v':2}],'right':[3]}
r['x']['items'].append(9)
r['left'][0]['v'] = 8
r['right'].append(4)
assert a == {'x':{'a':1,'items':[1]},'left':[{'v':2}]}
assert b == {'x':{'b':2},'right':[3]}
assert deep_merge({'a':{'b':1},'c':[1]}, {'a':None,'c':[2]}) == {'a':None,'c':[2]}
assert deep_merge({}, {}) == {}
